// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        // Initial owner is address(0). Any caller other than the owner is not authorized.
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());

        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        // General rule: a non-owner can never change ownership, so the call must
        // revert (and the owner getter must remain unchanged).
        assertTrue(!ok && c.owner() == address(0));
    }
}
